   <style>
     :root {
       --bg: #fffafc;
       --surface: rgba(255, 255, 255, 0.86);
       --surface-strong: #ffffff;
       --text: #1f1521;
       --muted: #6f6372;
       --brand: #9b3db1;
       --brand-dark: #7b2b8d;
       --brand-soft: #f4e6f7;
       --line: rgba(155, 61, 177, 0.12);
       --shadow: 0 18px 40px rgba(123, 43, 141, 0.12);
       --radius: 28px;
     }

     * { box-sizing: border-box; }
     html { scroll-behavior: smooth; }
     body {
       margin: 0;
       font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top left, rgba(155, 61, 177, 0.12), transparent 32%),
         radial-gradient(circle at top right, rgba(244, 230, 247, 0.9), transparent 28%),
         linear-gradient(180deg, #fff 0%, var(--bg) 100%);
     }

     a { color: inherit; text-decoration: none; }
     .wrap { max-width: 1180px; margin: 0 auto; padding: 24px; }
     .hero {
       display: grid;
       grid-template-columns: 1.15fr 0.85fr;
       gap: 24px;
       align-items: stretch;
       margin-top: 10px;
     }
     .panel {
       background: var(--surface);
       backdrop-filter: blur(10px);
       border: 1px solid var(--line);
       border-radius: var(--radius);
       box-shadow: var(--shadow);
     }
     .hero-main {
       padding: 30px;
       overflow: hidden;
       position: relative;
     }
     .hero-main::after {
       content: "";
       position: absolute;
       inset: auto -120px -120px auto;
       width: 280px;
       height: 280px;
       background: radial-gradient(circle, rgba(155, 61, 177, 0.18), transparent 68%);
       pointer-events: none;
     }
     .brand-row {
       display: flex;
       gap: 18px;
       align-items: center;
       margin-bottom: 22px;
     }
     .brand-logo {
       width: 88px;
       height: 88px;
       border-radius: 24px;
       background: #fff;
       border: 1px solid rgba(155, 61, 177, 0.12);
       object-fit: contain;
       padding: 8px;
       flex: 0 0 auto;
     }

